func newFeedback() unsafe.Pointer { return unsafe.Pointer(new(aifeedback.Feedback)) }

func newNFeedback(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]aifeedback.Feedback, n)))
}

func ptrFeedback(p unsafe.Pointer, c int32) any {
	r := (*aifeedback.Feedback)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.UserID))
	case 4:
		return (*string)(unsafe.Pointer(&r.TargetType))
	case 5:
		return (*string)(unsafe.Pointer(&r.TargetID))
	case 6:
		return &r.TargetPart
	case 7:
		return (**string)(unsafe.Pointer(&r.ThreadID))
	case 8:
		return (**string)(unsafe.Pointer(&r.TurnID))
	case 9:
		return (**string)(unsafe.Pointer(&r.RunID))
	case 10:
		return (**string)(unsafe.Pointer(&r.AgentDefinitionID))
	case 11:
		return &r.DefinitionVersion
	case 12:
		return &r.DetectorKey
	case 13:
		return &r.Task
	case 14:
		return &r.Model
	case 15:
		return (**string)(unsafe.Pointer(&r.ProviderID))
	case 16:
		return &r.PromptHash
	case 17:
		return &r.ToolSpecHash
	case 18:
		return (*string)(unsafe.Pointer(&r.FingerprintSource))
	case 19:
		return (*int16)(unsafe.Pointer(&r.Rating))
	case 20:
		return (*[]string)(unsafe.Pointer(&r.Reasons))
	case 21:
		return &r.Comment
	case 22:
		return &r.TurnSnapshot
	case 23:
		return &r.PatternKey
	case 24:
		return (**string)(unsafe.Pointer(&r.EvalCaseID))
	case 25:
		return &r.Version
	case 26:
		return &r.CreatedAt
	case 27:
		return &r.UpdatedAt
	}
	return nil
}

func valueFeedback(p unsafe.Pointer, c int32) any {
	r := (*aifeedback.Feedback)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return string(r.UserID)
	case 4:
		return string(r.TargetType)
	case 5:
		return string(r.TargetID)
	case 6:
		return r.TargetPart
	case 7:
		if r.ThreadID == nil {
			return nil
		}
		return string(*r.ThreadID)
	case 8:
		if r.TurnID == nil {
			return nil
		}
		return string(*r.TurnID)
	case 9:
		if r.RunID == nil {
			return nil
		}
		return string(*r.RunID)
	case 10:
		if r.AgentDefinitionID == nil {
			return nil
		}
		return string(*r.AgentDefinitionID)
	case 11:
		if r.DefinitionVersion == nil {
			return nil
		}
		return *r.DefinitionVersion
	case 12:
		if r.DetectorKey == "" {
			return nil
		}
		return r.DetectorKey
	case 13:
		if r.Task == "" {
			return nil
		}
		return r.Task
	case 14:
		if r.Model == "" {
			return nil
		}
		return r.Model
	case 15:
		if r.ProviderID == nil {
			return nil
		}
		return string(*r.ProviderID)
	case 16:
		if r.PromptHash == "" {
			return nil
		}
		return r.PromptHash
	case 17:
		if r.ToolSpecHash == "" {
			return nil
		}
		return r.ToolSpecHash
	case 18:
		return string(r.FingerprintSource)
	case 19:
		return int16(r.Rating)
	case 20:
		if r.Reasons == nil {
			return []string{}
		}
		return keel.Strings(r.Reasons)
	case 21:
		if r.Comment == "" {
			return nil
		}
		return r.Comment
	case 22:
		if r.TurnSnapshot == nil {
			return nil
		}
		return *r.TurnSnapshot
	case 23:
		return r.PatternKey
	case 24:
		if r.EvalCaseID == nil {
			return nil
		}
		return string(*r.EvalCaseID)
	case 25:
		return r.Version
	case 26:
		return r.CreatedAt
	case 27:
		return r.UpdatedAt
	}
	return nil
}

